package facade

import (
	"bytes"
	"fmt"
	"go/ast"
	"go/token"
	"go/types"
	"path"
	"slices"
	"strconv"
	"strings"
)

// header opens every generated file: the license lines the
// repository stamps on hand-written sources, and the marker that
// exempts generated ones from the tools that would restamp them.
const header = `// Copyright ThesmOS B.V. 2026
// SPDX-License-Identifier: Apache-2.0

// Code generated by internal/gen/facade. DO NOT EDIT.

`

// An importGroup orders the generated import block the way the
// repository's formatter sections it: standard library, external
// modules, eidos modules.
type importGroup int

const (
	groupStd importGroup = iota
	groupExternal
	groupEidos
)

// importRec is one import the generated file needs: the path the
// import line spells — the facade sibling for a respelt kernel
// package — the qualifier its selectors print, and whether the
// import line names it.
type importRec struct {
	path  string
	qual  string
	named bool
	group importGroup
}

// renderer accumulates one facade package: the re-exported
// declarations in kernel source order, and the imports their
// spellings pulled in.
type renderer struct {
	ps      *PackageSurface
	curated map[string]string

	imports map[string]importRec // import path -> record
	quals   map[string]string    // qualifier -> import path
	names   map[string]string    // current file: local name -> import path
	tparams map[string]bool      // type parameters in scope

	body bytes.Buffer
}

// render re-exports one parsed surface as facade source: exported
// types become aliases, constants and variables re-declare, and
// functions wrap, each carrying its kernel documentation with
// kernel module paths respelt to facade ones.
func render(ps *PackageSurface, curated map[string]string) ([]byte, error) {
	r := &renderer{
		ps:      ps,
		curated: curated,
		imports: map[string]importRec{},
		quals:   map[string]string{},
		tparams: map[string]bool{},
	}
	r.imports[ps.KernelPath] = importRec{
		path: ps.KernelPath, qual: counterpartAlias, named: true, group: groupEidos,
	}
	r.quals[counterpartAlias] = ps.KernelPath

	exported := 0
	for _, f := range ps.Files {
		r.fileNames(f)
		for _, d := range f.Decls {
			n, err := r.decl(d)
			if err != nil {
				return nil, err
			}
			exported += n
		}
	}
	if exported == 0 {
		return nil, fmt.Errorf("facade: %s re-exports nothing", ps.KernelPath)
	}
	return r.file(), nil
}

// decl renders one top-level declaration, returning how many
// exported symbols it re-exported.
func (r *renderer) decl(d ast.Decl) (int, error) {
	switch d := d.(type) {
	case *ast.FuncDecl:
		if d.Recv != nil || !ast.IsExported(d.Name.Name) {
			return 0, nil
		}
		return 1, r.fn(d)
	case *ast.GenDecl:
		switch d.Tok {
		case token.CONST, token.VAR:
			return r.values(d)
		case token.TYPE:
			return r.aliases(d)
		default:
			return 0, nil
		}
	default:
		return 0, nil
	}
}

// fn wraps one exported function: the same signature, the body one
// call through to the kernel, type arguments instantiated
// explicitly so inference never decides differently than the
// original.
func (r *renderer) fn(d *ast.FuncDecl) error {
	defer clear(r.tparams)

	tpDecl, tpInst, err := r.typeParams(d.Type.TypeParams)
	if err != nil {
		return err
	}
	params, args, err := r.params(d.Type.Params)
	if err != nil {
		return err
	}
	results, err := r.results(d.Type.Results)
	if err != nil {
		return err
	}

	r.comments(d.Doc)
	keyword := "return "
	if d.Type.Results == nil || len(d.Type.Results.List) == 0 {
		keyword = ""
	}
	fmt.Fprintf(&r.body, "func %s%s(%s)%s {\n\t%s%s.%s%s(%s)\n}\n\n",
		d.Name.Name, tpDecl, params, results,
		keyword, counterpartAlias, d.Name.Name, tpInst, args)
	return nil
}

// values re-declares a const or var group: one name per line, the
// value the kernel's, so the type and the untypedness both carry
// over from the right-hand side.
func (r *renderer) values(d *ast.GenDecl) (int, error) {
	kw := "const"
	if d.Tok == token.VAR {
		kw = "var"
	}

	var lines []string
	count := 0
	for _, spec := range d.Specs {
		vs, ok := spec.(*ast.ValueSpec)
		if !ok {
			return 0, r.ps.at(spec.Pos(), "unexpected %s spec", kw)
		}
		var owned []string
		for _, name := range vs.Names {
			if !ast.IsExported(name.Name) {
				continue
			}
			owned = append(owned, fmt.Sprintf("%s = %s.%s", name.Name, counterpartAlias, name.Name))
		}
		if len(owned) == 0 {
			continue
		}
		if trail := commentText(vs.Comment); trail != "" {
			owned[len(owned)-1] += " " + trail
		}
		lines = append(lines, r.docLines(vs.Doc)...)
		lines = append(lines, owned...)
		count += len(owned)
	}
	if count == 0 {
		return 0, nil
	}

	r.comments(d.Doc)
	if len(lines) == 1 && !d.Lparen.IsValid() {
		fmt.Fprintf(&r.body, "%s %s\n\n", kw, lines[0])
		return count, nil
	}
	fmt.Fprintf(&r.body, "%s (\n\t%s\n)\n\n", kw, strings.Join(lines, "\n\t"))
	return count, nil
}

// aliases re-declares a type group as aliases, generic parameters
// carried over so a parameterized kernel type stays one type under
// both spellings.
func (r *renderer) aliases(d *ast.GenDecl) (int, error) {
	var lines []string
	count := 0
	for _, spec := range d.Specs {
		ts, ok := spec.(*ast.TypeSpec)
		if !ok {
			return 0, r.ps.at(spec.Pos(), "unexpected type spec")
		}
		if !ast.IsExported(ts.Name.Name) {
			continue
		}
		tpDecl, tpInst, err := r.typeParams(ts.TypeParams)
		clear(r.tparams)
		if err != nil {
			return 0, err
		}
		line := fmt.Sprintf("%s%s = %s.%s%s",
			ts.Name.Name, tpDecl, counterpartAlias, ts.Name.Name, tpInst)
		if trail := commentText(ts.Comment); trail != "" {
			line += " " + trail
		}
		lines = append(lines, r.docLines(ts.Doc)...)
		lines = append(lines, line)
		count++
	}
	if count == 0 {
		return 0, nil
	}

	r.comments(d.Doc)
	if len(lines) == 1 && !d.Lparen.IsValid() {
		fmt.Fprintf(&r.body, "type %s\n\n", lines[0])
		return count, nil
	}
	fmt.Fprintf(&r.body, "type (\n\t%s\n)\n\n", strings.Join(lines, "\n\t"))
	return count, nil
}

// typeParams renders a type-parameter list twice: the declaration
// form with constraints, and the instantiation form with names
// alone. It registers every name, so parameter references print
// verbatim inside the declaration's expressions.
func (r *renderer) typeParams(fl *ast.FieldList) (decl, inst string, err error) {
	if fl == nil || len(fl.List) == 0 {
		return "", "", nil
	}
	var decls, names []string
	for _, f := range fl.List {
		for _, name := range f.Names {
			r.tparams[name.Name] = true
			names = append(names, name.Name)
		}
		constraint, err := r.expr(f.Type)
		if err != nil {
			return "", "", err
		}
		group := make([]string, 0, len(f.Names))
		for _, name := range f.Names {
			group = append(group, name.Name)
		}
		decls = append(decls, strings.Join(group, ", ")+" "+constraint)
	}
	return "[" + strings.Join(decls, ", ") + "]", "[" + strings.Join(names, ", ") + "]", nil
}

// params renders a wrapper's parameter list and the argument list
// forwarding it. A parameter the kernel left unnamed or blank gets
// a fresh name, because the wrapper has to pass it on.
func (r *renderer) params(fl *ast.FieldList) (decl, args string, err error) {
	if fl == nil || len(fl.List) == 0 {
		return "", "", nil
	}

	used := map[string]bool{}
	for _, f := range fl.List {
		for _, name := range f.Names {
			used[name.Name] = true
		}
	}
	fresh := func() string {
		for i := 0; ; i++ {
			name := fmt.Sprintf("a%d", i)
			if !used[name] {
				used[name] = true
				return name
			}
		}
	}

	var decls, forwards []string
	for _, f := range fl.List {
		typ, err := r.expr(f.Type)
		if err != nil {
			return "", "", err
		}
		_, variadic := f.Type.(*ast.Ellipsis)

		names := make([]string, 0, max(len(f.Names), 1))
		if len(f.Names) == 0 {
			names = append(names, fresh())
		}
		for _, name := range f.Names {
			if name.Name == "_" {
				names = append(names, fresh())
				continue
			}
			names = append(names, name.Name)
		}

		decls = append(decls, strings.Join(names, ", ")+" "+typ)
		for _, name := range names {
			if variadic {
				name += "..."
			}
			forwards = append(forwards, name)
		}
	}
	return strings.Join(decls, ", "), strings.Join(forwards, ", "), nil
}

// results renders a wrapper's result list, names carried over
// verbatim: nothing forwards out of a result, so nothing needs
// renaming.
func (r *renderer) results(fl *ast.FieldList) (string, error) {
	if fl == nil || len(fl.List) == 0 {
		return "", nil
	}
	var decls []string
	for _, f := range fl.List {
		typ, err := r.expr(f.Type)
		if err != nil {
			return "", err
		}
		if len(f.Names) == 0 {
			decls = append(decls, typ)
			continue
		}
		group := make([]string, 0, len(f.Names))
		for _, name := range f.Names {
			group = append(group, name.Name)
		}
		decls = append(decls, strings.Join(group, ", ")+" "+typ)
	}
	if len(decls) == 1 && len(fl.List[0].Names) == 0 {
		return " " + decls[0], nil
	}
	return " (" + strings.Join(decls, ", ") + ")", nil
}

// expr prints one type expression with qualifiers respelt: a
// curated kernel package prints under its facade sibling, anything
// else keeps its source spelling. A form re-export cannot carry —
// an anonymous struct, an interface with methods, an unexported
// name — is refused at its position.
func (r *renderer) expr(e ast.Expr) (string, error) {
	switch e := e.(type) {
	case *ast.Ident:
		return r.ident(e)
	case *ast.SelectorExpr:
		x, ok := e.X.(*ast.Ident)
		if !ok {
			return "", r.ps.at(e.Pos(), "unsupported qualified expression")
		}
		qual, err := r.qualify(x)
		if err != nil {
			return "", err
		}
		return qual + "." + e.Sel.Name, nil
	case *ast.StarExpr:
		inner, err := r.expr(e.X)
		return "*" + inner, err
	case *ast.Ellipsis:
		inner, err := r.expr(e.Elt)
		return "..." + inner, err
	case *ast.ArrayType:
		elt, err := r.expr(e.Elt)
		if err != nil {
			return "", err
		}
		if e.Len == nil {
			return "[]" + elt, nil
		}
		length, err := r.expr(e.Len)
		return "[" + length + "]" + elt, err
	case *ast.MapType:
		key, err := r.expr(e.Key)
		if err != nil {
			return "", err
		}
		value, err := r.expr(e.Value)
		return "map[" + key + "]" + value, err
	case *ast.ChanType:
		inner, err := r.expr(e.Value)
		switch e.Dir {
		case ast.SEND:
			return "chan<- " + inner, err
		case ast.RECV:
			return "<-chan " + inner, err
		default:
			return "chan " + inner, err
		}
	case *ast.FuncType:
		return r.funcType(e)
	case *ast.ParenExpr:
		inner, err := r.expr(e.X)
		return "(" + inner + ")", err
	case *ast.IndexExpr:
		return r.index(e.X, e.Index)
	case *ast.IndexListExpr:
		return r.index(e.X, e.Indices...)
	case *ast.BinaryExpr:
		left, err := r.expr(e.X)
		if err != nil {
			return "", err
		}
		right, err := r.expr(e.Y)
		return left + " " + e.Op.String() + " " + right, err
	case *ast.UnaryExpr:
		inner, err := r.expr(e.X)
		return e.Op.String() + inner, err
	case *ast.InterfaceType:
		return r.interfaceType(e)
	case *ast.BasicLit:
		return e.Value, nil
	default:
		return "", r.ps.at(e.Pos(), "unsupported %T in an exported signature", e)
	}
}

// index prints an instantiated generic type.
func (r *renderer) index(x ast.Expr, indices ...ast.Expr) (string, error) {
	base, err := r.expr(x)
	if err != nil {
		return "", err
	}
	args := make([]string, 0, len(indices))
	for _, idx := range indices {
		arg, err := r.expr(idx)
		if err != nil {
			return "", err
		}
		args = append(args, arg)
	}
	return base + "[" + strings.Join(args, ", ") + "]", nil
}

// funcType prints a function type appearing inside a signature.
// Parameter names carry verbatim: nothing forwards through a type,
// so nothing needs renaming.
func (r *renderer) funcType(ft *ast.FuncType) (string, error) {
	var decls []string
	if ft.Params != nil {
		for _, f := range ft.Params.List {
			typ, err := r.expr(f.Type)
			if err != nil {
				return "", err
			}
			if len(f.Names) == 0 {
				decls = append(decls, typ)
				continue
			}
			group := make([]string, 0, len(f.Names))
			for _, name := range f.Names {
				group = append(group, name.Name)
			}
			decls = append(decls, strings.Join(group, ", ")+" "+typ)
		}
	}
	results, err := r.results(ft.Results)
	if err != nil {
		return "", err
	}
	return "func(" + strings.Join(decls, ", ") + ")" + results, nil
}

// interfaceType prints a constraint interface: embedded elements
// and unions only. An anonymous interface declaring methods would
// re-declare rather than re-export, so it is refused.
func (r *renderer) interfaceType(it *ast.InterfaceType) (string, error) {
	if it.Methods == nil || len(it.Methods.List) == 0 {
		return "interface{}", nil
	}
	var elems []string
	for _, f := range it.Methods.List {
		if len(f.Names) > 0 {
			return "", r.ps.at(f.Pos(), "anonymous interface with methods in an exported signature")
		}
		elem, err := r.expr(f.Type)
		if err != nil {
			return "", err
		}
		elems = append(elems, elem)
	}
	return "interface{ " + strings.Join(elems, "; ") + " }", nil
}

// ident prints a bare identifier: a type parameter, a universe
// name or an exported name, which the facade's own alias resolves.
// An unexported name in an exported signature has no facade
// spelling, so it is refused.
func (r *renderer) ident(id *ast.Ident) (string, error) {
	switch {
	case r.tparams[id.Name], ast.IsExported(id.Name), types.Universe.Lookup(id.Name) != nil:
		return id.Name, nil
	default:
		return "", r.ps.at(id.Pos(), "unexported %s in an exported signature cannot re-export", id.Name)
	}
}

// fileNames records one file's import table, the map a qualified
// reference resolves against.
func (r *renderer) fileNames(f *ast.File) {
	r.names = map[string]string{}
	for _, imp := range f.Imports {
		p, err := strconv.Unquote(imp.Path.Value)
		if err != nil {
			continue
		}
		name := path.Base(p)
		if imp.Name != nil {
			name = imp.Name.Name
		}
		if name == "_" {
			continue
		}
		r.names[name] = p
	}
}

// qualify resolves a selector's qualifier to the name it prints in
// the facade, registering the import it needs.
func (r *renderer) qualify(id *ast.Ident) (string, error) {
	p, known := r.names[id.Name]
	if !known {
		return "", r.ps.at(id.Pos(), "qualifier %s resolves to no import", id.Name)
	}
	if rec, seen := r.imports[p]; seen {
		return rec.qual, nil
	}

	rec, err := r.classify(p, id)
	if err != nil {
		return "", err
	}
	if owner, taken := r.quals[rec.qual]; taken && owner != p {
		return "", r.ps.at(id.Pos(), "import name %s serves both %s and %s", rec.qual, owner, p)
	}
	r.imports[p] = rec
	r.quals[rec.qual] = p
	return rec.qual, nil
}

// classify decides how one imported path spells in the facade: a
// curated kernel package respells to its facade sibling, a kernel
// package outside the curated list is a surface leak and refused,
// and everything else keeps its source spelling.
func (r *renderer) classify(p string, id *ast.Ident) (importRec, error) {
	if p == KernelModule || strings.HasPrefix(p, KernelModule+"/") {
		rel := strings.TrimPrefix(strings.TrimPrefix(p, KernelModule), "/")
		name, ok := r.curated[rel]
		if rel == "" || !ok {
			return importRec{}, r.ps.at(id.Pos(),
				"%s leaks into the exported surface without a facade package", p)
		}
		return importRec{path: FacadeModule + "/" + name, qual: name, group: groupEidos}, nil
	}

	group := groupExternal
	if first, _, _ := strings.Cut(p, "/"); !strings.Contains(first, ".") {
		group = groupStd
	}
	return importRec{path: p, qual: id.Name, named: id.Name != path.Base(p), group: group}, nil
}

// comments writes a documentation block, kernel module paths
// respelt to facade ones so carried documentation links stay
// inside the facade namespace.
func (r *renderer) comments(cg *ast.CommentGroup) {
	for _, line := range r.docLines(cg) {
		r.body.WriteString(line + "\n")
	}
}

// docLines returns a comment group's raw lines with kernel module
// paths respelt; nil in, nothing out.
func (r *renderer) docLines(cg *ast.CommentGroup) []string {
	if cg == nil {
		return nil
	}
	lines := make([]string, 0, len(cg.List))
	for _, c := range cg.List {
		for line := range strings.Lines(c.Text) {
			lines = append(lines, strings.TrimRight(
				strings.ReplaceAll(line, KernelModule, FacadeModule), "\n",
			))
		}
	}
	return lines
}

// commentText flattens a trailing comment onto one line.
func commentText(cg *ast.CommentGroup) string {
	if cg == nil {
		return ""
	}
	parts := make([]string, 0, len(cg.List))
	for _, c := range cg.List {
		parts = append(parts, strings.ReplaceAll(c.Text, KernelModule, FacadeModule))
	}
	return strings.Join(parts, " ")
}

// file assembles the generated source: header, package
// documentation, package clause, imports, body.
func (r *renderer) file() []byte {
	var out bytes.Buffer
	out.WriteString(header)
	out.WriteString(r.packageDoc())
	fmt.Fprintf(&out, "package %s\n\n", r.ps.Name)
	out.WriteString(r.importBlock())
	out.Write(r.body.Bytes())
	return out.Bytes()
}

// packageDoc composes the facade package's documentation: what the
// package re-exports, and the dependency position computed from
// the imports the surface actually pulled in.
func (r *renderer) packageDoc() string {
	var out strings.Builder
	if r.ps.Rel == "" {
		out.WriteString(`// Package sdk re-exports the kernel's authoring surface, the
// plugin facade and the backend kit of [go.dokimi.dev/eidos/core]:
// one alias, constant or wrapper per exported symbol, defining
// nothing of its own. Plugin modules import the facade's paths
// alone; the kernel arrives as a transitive dependency and stays
// the single home of every definition, so each symbol here
// carries the kernel's documentation.
`)
	} else {
		fmt.Fprintf(&out, `// Package %s re-exports [%s]:
// one alias, constant or wrapper per exported symbol, so plugin
// code speaks the facade's paths while the kernel package stays
// the single home of every definition.
`, r.ps.Name, r.ps.KernelPath)
	}

	out.WriteString("//\n// # Dependency position\n//\n")
	sentence := fmt.Sprintf("%s imports %s.", r.subject(), prose(r.dependencies()))
	for _, line := range wrap(sentence, docWidth) {
		out.WriteString("// " + line + "\n")
	}
	return out.String()
}

// docWidth is where generated documentation wraps, matching the
// hand-written kernel docblocks beside it.
const docWidth = 64

// wrap greedily wraps a sentence into lines of at most width
// runes, never splitting a word.
func wrap(s string, width int) []string {
	var lines []string
	line := ""
	for word := range strings.FieldsSeq(s) {
		switch {
		case line == "":
			line = word
		case len(line)+1+len(word) <= width:
			line += " " + word
		default:
			lines = append(lines, line)
			line = word
		}
	}
	if line != "" {
		lines = append(lines, line)
	}
	return lines
}

// subject is the package's short spelling in its own dependency
// position, mirroring how the kernel packages state theirs.
func (r *renderer) subject() string {
	if rel := r.ps.FacadeRel(); rel != "" {
		return "sdk/" + rel
	}
	return "sdk"
}

// dependencies lists what the generated file imports, shortest
// spelling first: the kernel counterpart, the facade siblings, the
// external modules, and the stdlib as one item.
func (r *renderer) dependencies() []string {
	counterpart := "core"
	if r.ps.Rel != "" {
		counterpart = "core/" + r.ps.Rel
	}

	var siblings, externals []string
	stdlib := false
	for p, rec := range r.imports {
		switch {
		case p == r.ps.KernelPath:
		case rec.group == groupEidos:
			siblings = append(siblings, "sdk/"+strings.TrimPrefix(rec.path, FacadeModule+"/"))
		case rec.group == groupExternal:
			externals = append(externals, rec.path)
		default:
			stdlib = true
		}
	}
	slices.Sort(siblings)
	slices.Sort(externals)

	deps := append([]string{counterpart}, siblings...)
	deps = append(deps, externals...)
	if stdlib {
		deps = append(deps, "the Go stdlib")
	}
	return deps
}

// importBlock renders the import declaration, grouped the way the
// repository's formatter sections it.
func (r *renderer) importBlock() string {
	grouped := map[importGroup][]string{}
	for _, rec := range r.imports {
		line := strconv.Quote(rec.path)
		if rec.named {
			line = rec.qual + " " + line
		}
		grouped[rec.group] = append(grouped[rec.group], line)
	}

	var sections []string
	for _, g := range []importGroup{groupStd, groupExternal, groupEidos} {
		if len(grouped[g]) == 0 {
			continue
		}
		lines := grouped[g]
		slices.SortFunc(lines, func(a, b string) int {
			return strings.Compare(pathOf(a), pathOf(b))
		})
		sections = append(sections, "\t"+strings.Join(lines, "\n\t"))
	}
	return "import (\n" + strings.Join(sections, "\n\n") + "\n)\n\n"
}

// pathOf returns an import line's quoted path, the key gci sorts
// by regardless of aliasing.
func pathOf(line string) string {
	if _, quoted, found := strings.Cut(line, " "); found {
		return quoted
	}
	return line
}

// prose joins a dependency list the way the kernel's package
// documentation does: commas, a final and.
func prose(items []string) string {
	switch len(items) {
	case 0:
		return ""
	case 1:
		return items[0]
	default:
		return strings.Join(items[:len(items)-1], ", ") + " and " + items[len(items)-1]
	}
}
